import{_ as e,o as s,c as a,aO as i}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"CycloneDDS CMake 构建配置：功能裁剪与依赖联动","description":"","frontmatter":{"date":"2026-11-13T11:00:00.000Z","title":"CycloneDDS CMake 构建配置：功能裁剪与依赖联动","source":[["1-知识/中间件/cyclone-dds/Eclipse Cyclone DDS CMake 构建配置"]],"tags":["CycloneDDS","DDS","CMake","教程手册"],"categories":["计算机"],"permalink":"/pages/fdcad5"},"headers":[],"relativePath":"计算机/CycloneDDS CMake 构建配置：功能裁剪与依赖联动.md","filePath":"计算机/CycloneDDS CMake 构建配置：功能裁剪与依赖联动.md","lastUpdated":1794534497000}'),l={name:"计算机/CycloneDDS CMake 构建配置：功能裁剪与依赖联动.md"};function n(d,t,r,h,p,o){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="cyclonedds-cmake-构建配置-功能裁剪与依赖联动" tabindex="-1">CycloneDDS CMake 构建配置：功能裁剪与依赖联动 <a class="header-anchor" href="#cyclonedds-cmake-构建配置-功能裁剪与依赖联动" aria-label="Permalink to &quot;CycloneDDS CMake 构建配置：功能裁剪与依赖联动&quot;">​</a></h1> <p>Eclipse Cyclone DDS 使用 CMake 构建。除了标准的 <code>CMAKE_BUILD_TYPE</code> 等选项，项目提供了一组 <code>-D</code> 标志控制功能模块的编译、外部依赖的查找与特定 QoS 策略的支持。合理配置这些选项可以缩小二进制体积、适配嵌入式环境。这篇文章按用途分组整理常用选项，并给出三种典型场景的组合示例。</p> <h2 id="构建目标与工具配置" tabindex="-1">构建目标与工具配置 <a class="header-anchor" href="#构建目标与工具配置" aria-label="Permalink to &quot;构建目标与工具配置&quot;">​</a></h2> <table tabindex="0"><thead><tr><th style="text-align:left;">选项</th> <th style="text-align:left;">说明</th></tr></thead> <tbody><tr><td style="text-align:left;"><code>-DBUILD_EXAMPLES=ON</code></td> <td style="text-align:left;">构建示例程序，适合学习 API 或验证安装</td></tr> <tr><td style="text-align:left;"><code>-DBUILD_TESTING=ON</code></td> <td style="text-align:left;">构建测试套件。注意：会强制导出库的所有符号，可能增大二进制并影响链接行为</td></tr> <tr><td style="text-align:left;"><code>-DBUILD_IDLC=NO</code></td> <td style="text-align:left;">不构建 IDL 编译器 <code>idlc</code>。影响：无法编译新的 IDL 文件，依赖 IDL 的示例、测试与 <code>ddsperf</code> 都无法构建</td></tr> <tr><td style="text-align:left;"><code>-DBUILD_DDSPERF=NO</code></td> <td style="text-align:left;">不构建 <code>ddsperf</code> 性能测量工具（基准测试与性能分析用）</td></tr> <tr><td style="text-align:left;"><code>-DBUILD_IDLC_XTESTS=NO</code></td> <td style="text-align:left;">不构建 IDL 编译器的额外测试集。机制：运行时用 C 后端动态编译 IDL 并构建测试程序。限制：不支持 Windows</td></tr></tbody></table> <h2 id="外部依赖与核心功能" tabindex="-1">外部依赖与核心功能 <a class="header-anchor" href="#外部依赖与核心功能" aria-label="Permalink to &quot;外部依赖与核心功能&quot;">​</a></h2> <h3 id="安全与加密-openssl" tabindex="-1">安全与加密（OpenSSL） <a class="header-anchor" href="#安全与加密-openssl" aria-label="Permalink to &quot;安全与加密（OpenSSL）&quot;">​</a></h3> <table tabindex="0"><thead><tr><th style="text-align:left;">选项</th> <th style="text-align:left;">说明</th></tr></thead> <tbody><tr><td style="text-align:left;"><code>-DENABLE_SSL=NO</code></td> <td style="text-align:left;">不查找 OpenSSL：移除 TLS/TCP 传输支持，不构建身份验证与加密的安全插件。默认 <code>AUTO</code>（检测到即启用）</td></tr> <tr><td style="text-align:left;"><code>-DENABLE_SECURITY=NO</code></td> <td style="text-align:left;">不构建安全接口与钩子。即使 <code>ENABLE_SSL=NO</code>，理论上仍可启用此项以加载第三方安全插件，但通常两者配合使用</td></tr></tbody></table> <h3 id="共享内存零拷贝-iceoryx" tabindex="-1">共享内存零拷贝（Iceoryx） <a class="header-anchor" href="#共享内存零拷贝-iceoryx" aria-label="Permalink to &quot;共享内存零拷贝（Iceoryx）&quot;">​</a></h3> <table tabindex="0"><thead><tr><th style="text-align:left;">选项</th> <th style="text-align:left;">说明</th></tr></thead> <tbody><tr><td style="text-align:left;"><code>-DENABLE_ICEORYX=NO</code></td> <td style="text-align:left;">不查找 Eclipse Iceoryx，禁用同机进程间零拷贝共享内存通信。默认 <code>AUTO</code></td></tr></tbody></table> <h2 id="qos-策略与协议特性裁剪" tabindex="-1">QoS 策略与协议特性裁剪 <a class="header-anchor" href="#qos-策略与协议特性裁剪" aria-label="Permalink to &quot;QoS 策略与协议特性裁剪&quot;">​</a></h2> <p>资源受限的嵌入式环境可以按需禁用：</p> <table tabindex="0"><thead><tr><th style="text-align:left;">选项</th> <th style="text-align:left;">功能</th> <th style="text-align:left;">依赖/联动限制</th></tr></thead> <tbody><tr><td style="text-align:left;"><code>-DENABLE_LIFESPAN=NO</code></td> <td style="text-align:left;">排除 Lifespan QoS（数据有效期）</td> <td style="text-align:left;">无</td></tr> <tr><td style="text-align:left;"><code>-DENABLE_DEADLINE_MISSED=NO</code></td> <td style="text-align:left;">排除 Deadline QoS（截止期限）</td> <td style="text-align:left;">无</td></tr> <tr><td style="text-align:left;"><code>-DENABLE_TYPELIB=NO</code></td> <td style="text-align:left;">排除类型库支持</td> <td style="text-align:left;"><strong>必须同时</strong> <code>-DENABLE_TYPE_DISCOVERY=NO -DENABLE_TOPIC_DISCOVERY=NO</code></td></tr> <tr><td style="text-align:left;"><code>-DENABLE_TYPE_DISCOVERY=NO</code></td> <td style="text-align:left;">排除类型发现与类型兼容性检查（大部分 XTypes 功能）</td> <td style="text-align:left;"><strong>必须同时</strong> <code>-DENABLE_TOPIC_DISCOVERY=NO</code></td></tr> <tr><td style="text-align:left;"><code>-DENABLE_TOPIC_DISCOVERY=NO</code></td> <td style="text-align:left;">排除主题发现支持</td> <td style="text-align:left;">无独立强依赖，常被上面两项联动</td></tr> <tr><td style="text-align:left;"><code>-DENABLE_SOURCE_SPECIFIC_MULTICAST=NO</code></td> <td style="text-align:left;">禁用源特定多播（SSM）</td> <td style="text-align:left;">QNX 平台建议同时禁用 IPv6</td></tr> <tr><td style="text-align:left;"><code>-DENABLE_IPV6=NO</code></td> <td style="text-align:left;">禁用 IPv6</td> <td style="text-align:left;">QNX 平台建议同时禁用 SSM</td></tr></tbody></table> <h2 id="配置组合示例" tabindex="-1">配置组合示例 <a class="header-anchor" href="#配置组合示例" aria-label="Permalink to &quot;配置组合示例&quot;">​</a></h2> <h3 id="最小化嵌入式构建" tabindex="-1">最小化嵌入式构建 <a class="header-anchor" href="#最小化嵌入式构建" aria-label="Permalink to &quot;最小化嵌入式构建&quot;">​</a></h3> <p>资源极度受限、只需要基本发布/订阅：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DCMAKE_BUILD_TYPE=Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DBUILD_EXAMPLES=OFF</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DBUILD_TESTING=OFF</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DBUILD_DDSPERF=OFF</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_SSL=NO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_ICEORYX=NO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_SECURITY=NO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_LIFESPAN=NO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_DEADLINE_MISSED=NO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_TYPE_DISCOVERY=NO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_TOPIC_DISCOVERY=NO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_IPV6=NO</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="安全增强构建" tabindex="-1">安全增强构建 <a class="header-anchor" href="#安全增强构建" aria-label="Permalink to &quot;安全增强构建&quot;">​</a></h3> <p>需要完整的认证、加密、访问控制：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_SSL=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_SECURITY=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DBUILD_TESTING=ON</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>前提：系统已安装 OpenSSL 开发库。</p> <h3 id="高性能同机通信构建" tabindex="-1">高性能同机通信构建 <a class="header-anchor" href="#高性能同机通信构建" aria-label="Permalink to &quot;高性能同机通信构建&quot;">​</a></h3> <p>主要场景是单节点内多进程通信：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DENABLE_ICEORYX=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DBUILD_EXAMPLES=ON</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>前提：系统已安装 Eclipse Iceoryx 库。构建出的库配合 XML 配置里的 PSMX 接口启用共享内存传输。</p> <h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2> <ol><li><strong>依赖连锁</strong>：禁用 <code>BUILD_IDLC</code> 会导致依赖代码生成的 <code>BUILD_EXAMPLES</code>、<code>BUILD_TESTING</code>、<code>BUILD_DDSPERF</code> 无法构建。通常保留 IDLC，或手动预生成代码。</li> <li><strong>类型系统完整性</strong>：<code>ENABLE_TYPE_DISCOVERY=NO</code> 会严重影响动态类型处理能力，应用依赖 XTypes 特性时不要禁用。</li> <li><strong>平台特异性</strong>：QNX 等实时系统上，网络协议栈的实现可能要求同时禁用 IPv6 与源特定多播，以具体平台的构建文档为准。</li></ol> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>三类选项各管一段：<code>BUILD_*</code> 管工具与测试，<code>ENABLE_SSL/SECURITY/ICEORYX</code> 管外部依赖特性，<code>ENABLE_*</code> QoS 裁剪管二进制体积。</li> <li>类型相关三个选项（TYPELIB/TYPE_DISCOVERY/TOPIC_DISCOVERY）有强制联动关系，单禁一个会配置失败或行为不一致。</li> <li>嵌入式最小集 = 关工具 + 关安全 + 关 iceoryx + 裁 QoS + 关 IPv6，但 XTypes 依赖方要留意类型发现的取舍。</li></ul>`,52)])])}const C=e(l,[["render",n]]);export{k as __pageData,C as default};
